nObserver(entries => {\r\n    entries.forEach(e => { if(e.isIntersecting){e.target.classList.add(\'visible\');obs.unobserve(e.target);} });\r\n  }, {threshold:0.1});\r\n  document.querySelectorAll(\'.fade-section\').forEach(el => obs.observe(el));\r\n</script>\r\n</body>\r\n</html>','','','','','',1,'2026-05-23 12:24:24','2026-05-26 17:08:17','amount',NULL,'product',NULL,'full_address',NULL,'date_jp',NULL,NULL,NULL,NULL,'',NULL,NULL),
