);color:#1a0f00;\r\n    box-shadow:0 0 30px rgba(255,215,0,.5),0 0 60px rgba(255,215,0,.2),inset 0 1px 1px rgba(255,255,255,.4);\r\n    animation:glow1 2.5s ease-in-out infinite!important;}\r\n  .rank-2{background:linear-gradient(135deg,#4a4a4a,#A8A8A8,#E8E8E8,#A8A8A8,#4a4a4a);color:#1a1a1a;box-shadow:0 0 20px rgba(200,200,200,.3);}\r\n  .rank-3{background:linear-gradient(135deg,#5C3A1E,#9E6E3A,#D4956A,#9E6E3A,#5C3A1E);color:#1a0f00;box-shadow:0 0 20px rgba(205,127,50,.3);}\r\n\r\n  .prize-info{font-size:14px;color:rgba(255,255,255,.92);letter-spacing:.1em;margin-top:8px;}\r\n  .prize-amount{font-size:13px;color:#FFD700;letter-spacing:.15em;margin-top:4px;}\r\n  .winner-count{font-size:13px;letter-spacing:.15em;margin-top:8px;}\r\n\r\n  .prize-img-wrap{text-align:center;margin:18px 0 28px;position:relative;z-index:1;}\r\n  .prize-img{width:160px;height:120px;object-fit:cover;border-radius:12px;\r\n    border:2px solid rgba(255,215,0,.3);box-shadow:0 0 30px rgba(255,215,0,.15),0 8px 32px rgba(0,0,0,.5);}\r\n  .rank-1-section .prize-img{width:200px;height:150px;border-color:var(--gold);box-shadow:0 0 50px rgba(255,215,0,.4),0 8px 32px rgba(0,0,0,.5);}\r\n\r\n  .winners-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px;}\r\n  .winner-card{background:rgba(255,255,255,.05);border:1px solid rgba(255,215,0,.15);border-radius:14px;\r\n    padding:18px 20px;display:flex;align-items:center;gap:14px;\r\n    transition:transform .2s,box-shadow .2s;position:relative;overflow:hidden;}\r\n  .winner-card::before{content:\'\';position:absolute;inset:0;\r\n    background:linear-gradient(135deg,rgba(255,215,0,.06) 0%,transparent 60%);pointer-events:none;}\r\n  .winner-card:hover{transform:translateY(-3px);box-shadow:0 8px 30px rgba(255,215,0,.15);}\r\n  .rank-1-section .winner-card{border-color:rgba(255,215,0,.4);background:rgba(255,215,0,.07);}\r\n  .winner-avatar{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-conte